OPC.userLogout({!! json_encode(auth()->user()->name) !!});
const BARU = {!! json_encode(route('admin.jadwal.baru')) !!}, BASE = {!! json_encode(route('admin.jadwal')) !!}, UBAH = {!! json_encode(url('/admin/jadwal')) !!};
const Q = new URLSearchParams(location.search);
const TUTORS = {!! json_encode($tutors->map(fn($t) => ['id' => $t->id, 'name' => $t->name])->values()) !!};
OPC.on('+ Buat Jadwal Baru', () => OPC.go(BARU)); OPC.on('Export Jadwal', () => OPC.go({!! json_encode(route('admin.export', 'jadwal')) !!}));
OPC.on('Lihat & Sesuaikan', () => { const r = document.querySelector('tr[data-status=bentrok]'); if (r) { r.scrollIntoView({behavior: 'smooth', block: 'center'}); r.style.outline = '2px solid #ef4444'; } });
function nav(k, v) { const u = new URL(location.href); u.searchParams.delete('page'); v ? u.searchParams.set(k, v) : u.searchParams.delete(k); location.href = u.toString(); }
// tab rentang
const tabs = ['Semua Sesi', 'Hari Ini', 'Minggu Ini', 'Bulan Ini'].map(t => OPC.find(t, {sel: 'button'})[0]); const keys = ['all', 'today', 'week', 'month'];
const cur = keys.indexOf({!! json_encode($range) !!});
let ready = false; const ap = OPC.choice(tabs, 0, k => { if (ready) nav('range', keys[k]); }); if (cur > 0) ap(cur); ready = true;
// select
const sels = [...document.querySelectorAll('select')]; const [sT, sR, sS] = sels;
if (Q.get('tutor')) sT.value = Q.get('tutor');
const rm = {'Home Visit (Rumah)': 'home_visit', 'Online (Zoom / Meet)': 'online', 'Studio 1 (Cabang)': 'studio', 'Studio 2 (Cabang)': 'studio'};
[...sR.options].forEach(o => { if (rm[o.textContent]) o.value = rm[o.textContent]; else if (!o.value) o.value = ''; });
if (Q.get('method')) sR.value = Q.get('method');
const sm = {'Berjalan': 'berjalan', 'Selesai': 'selesai', 'Akan Datang': 'akan', 'Bentrok': 'bentrok'};
[...sS.options].forEach(o => { o.value = sm[o.textContent] || ''; }); if (Q.get('status')) sS.value = Q.get('status');
sT.addEventListener('change', () => nav('tutor', sT.value)); sR.addEventListener('change', () => nav('method', sR.value)); sS.addEventListener('change', () => nav('status', sS.value));
const qi = document.querySelector('input[placeholder^="Cari tutor"]'); qi.value = Q.get('q') || '';
qi.addEventListener('keydown', e => { if (e.key === 'Enter') { e.preventDefault(); nav('q', qi.value); } });
const rows = [...document.querySelectorAll('tbody tr[data-id]')]; qi.addEventListener('input', () => { const v = qi.value.toLowerCase(); rows.forEach(r => r.style.display = r.textContent.toLowerCase().includes(v) ? '' : 'none'); });
OPC.on('Filter Tambahan', () => OPC.toast('Gunakan filter Tutor, Ruangan, dan Status di sebelah kiri.', true), {sel: 'button[title="Filter Tambahan"]', exact: false});
document.querySelectorAll('button[title="Filter Tambahan"]').forEach(b => b.addEventListener('click', () => { document.querySelectorAll('select').forEach(s => s.value = ''); location.href = BASE; }));
// ubah / resolusi / batal
function reschedule(id) { OPC.go(BARU + '?ubah=' + id); }
window.SESS = {!! json_encode($sessionsJson) !!};
rows.forEach(r => { r.dataset.json = JSON.stringify(window.SESS[r.dataset.id] || {}); });
document.addEventListener('click', e => { const b = e.target.closest('tr[data-id] button'); if (!b) return; const r = b.closest('tr'); const t = OPC.label(b); const id = r.dataset.id;
  if (t === 'Ubah' || t === 'Resolusi') reschedule(id);
  else if (t === '' ) { if (confirm('Batalkan sesi ini?')) OPC.post(UBAH + '/' + id + '/batal', {}).then(j => OPC.done(j, 'reload')).catch(() => {}); } });
// kalender
OPC.on('Kalender', () => {
  const by = {}; Object.values(window.SESS).forEach(s => { (by[s.date] = by[s.date] || []).push(s); });
  const days = Object.keys(by).sort();
  const ov = document.createElement('div'); ov.style.cssText = 'position:fixed;inset:0;z-index:99990;background:rgba(19,27,46,.45);display:flex;align-items:center;justify-content:center;padding:16px';
  ov.innerHTML = '<div style="background:#fff;border-radius:20px;max-width:900px;width:100%;max-height:85vh;overflow:auto;padding:24px;font-family:inherit"><div style="display:flex;justify-content:space-between;margin-bottom:12px"><b style="font-size:16px">Kalender Sesi (halaman ini)</b><button data-x style="border:0;background:none;font-size:22px;cursor:pointer">&times;</button></div><div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:12px">' +
    (days.length ? days.map(d => '<div style="border:1px solid #e2e8f0;border-radius:12px;padding:10px"><div style="font-weight:700;font-size:12px;margin-bottom:6px">' + by[d][0].date_label + '</div>' + by[d].map(s => '<div style="font-size:11px;padding:4px 0;border-top:1px dashed #e2e8f0"><b>' + s.start + '–' + s.end + '</b> ' + s.student + '<br><span style="color:#64748b">' + s.tutor + ' • ' + s.method + '</span></div>').join('') + '</div>').join('') : '<div style="font-size:12px;color:#64748b">Tidak ada sesi.</div>') + '</div></div>';
  document.body.appendChild(ov); ov.addEventListener('click', e => { if (e.target === ov || e.target.dataset.x !== undefined) ov.remove(); });
}, {sel: 'button'});
OPC.on('Tabel', () => {}, {sel: 'button'});
</script></body></html>